insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D4-S1-001', 'source'::public.t3a_content_family, 'The figure from the floor', 'D4', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D4-S1-001", "title": "The figure from the floor", "stage": 1, "stage_code": "S1", "demonstration": true, "serving_eligible": false, "scenario_class": "observation_ready", "d4_situation_class": "SC-D4-1", "interaction_pattern_family_id": "IPF-D4-01", "administration_form_id": "AF-S1-SEQUENTIAL-REVEAL", "name_clearance_claim": "CLEARED", "compatibility_class": null, "source_sheet": {"source_sheet_text": "`recipient_roles`: RR-01 the head of department (`intended_recipient`); RR-02 the forty in the room; RR-03 the review sponsor. `material_items`: MI-01 that three of five suppliers were reviewed; MI-02 that the cost comparison covers three only; MI-03 that the conclusion is not signed off; MI-04 that two contracts expire this year. `designated_answer_contents`: AC-01 that no supplier selection has been made; AC-02 what remains before one can be. `unconfirmed_items`: UC-01 the review conclusion; UC-02 the two unreviewed suppliers. `available_channels` — not_applicable, Stage 1 written response, the Section 5.4 rules applies. `designated_points`: R2 and R4 in the room. `question_put`: \"So which supplier are we going with?\" at R4. `contradicted_attribution`: explicit none, so Q-D4-06 is not served. `adverse_effect_party`: explicit none. `escalation_state`: the review is being discussed in front of forty people who were not party to it. `conflicting_instructions`: explicit none. `ungrantable_request`: a supplier selection, which the record cannot support. `statement_test_point`: R6, putting an assertion the record contradicts. `stated_standard`: \"the review''s conclusion has not been signed off.\" Exact text at R1. `unsupported_inferences`: that a short answer is better; that declining to name a supplier was cautious. `irrelevant_conduct`: how the participant sounded; the suppliers'' merits.", "d4_situation_class": "SC-D4-1"}, "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable roles"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "On A2 or A3"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "On A1"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "R2 asks for the words"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "On A1"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A closed question at R4"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "On A1"}, {"question": "Q-D4-05", "state": "DIRECT", "basis": "Two unconfirmed items"}, {"question": "Q-D4-05b", "state": "CONDITIONAL", "basis": "On A1 or A2"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "No contradicted attribution. NO ANSWER ROW, NO MISSING-STATE CODE"}, {"question": "Q-D4-07", "state": "NOT SERVED", "basis": "A written response cannot evidence a channel used. NO ANSWER ROW, NO MISSING-STATE CODE"}, {"question": "Q-D4-07b", "state": "NOT SERVED", "basis": "Its parent is not served"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "R5 asks what goes out and by when"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "Test point at R6, and A3 is reachable"}], "script": null, "reveals": [], "text_blocks": {"The situation as the participant meets it": "You are at a department meeting of about forty people. The head of department is presenting and turns to you without warning: \"You''ve been on the supplier review — what''s the headline?\"\nWhat the record shows: three of the five suppliers were reviewed and two were not; the two reviewed favourably both hold contracts expiring this year; the cost comparison is complete for three suppliers only; and the review''s conclusion has not been signed off."}, "narrative": {"The situation as the participant meets it": "> You are at a department meeting of about forty people. The head of department is presenting and turns to you without warning: \"You''ve been on the supplier review — what''s the headline?\"\n>\n> What the record shows: three of the five suppliers were reviewed and two were not; the two reviewed favourably both hold contracts expiring this year; the cost comparison is complete for three suppliers only; and the review''s conclusion has not been signed off.", "Reveal sequence": "R1 the situation. R2 QUESTION: what do you say, word for word? R3 QUESTION: who are you addressing? R4 the head of department asks \"So which supplier are we going with?\" — QUESTION: what do you say? R5 QUESTION: what goes out afterwards, to whom, by when? R6 STATEMENT TEST: later the head of department says \"You told the room the review is finished. Is it?\" — QUESTION: what do you say?", "What this fixture proves": "Q-D4-06 and Q-D4-07 are NOT SERVED and write no row, while every other D4 element is served from a written response. A build that writes a null, a not_applicable or a forced answer for an unserved question, or that withholds an element D4 serves at Stage 1, has failed."}, "source_version_hash": "1044a0c13273ddb430187c949a90144dc29da4e039b99d024330ad6295b84a3a"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D4-S1-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
insert into public.t3a_source_authorship(source_version_id, source_author_identity) select v.content_version_id, array['DEMONSTRATION_AUTHOR'] from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D4-S1-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 1, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D4-S1-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 2, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D4-S1-001' on conflict do nothing;
insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D4-S2-001', 'source'::public.t3a_content_family, 'The line read back without its condition', 'D4', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D4-S2-001", "title": "The line read back without its condition", "stage": 2, "stage_code": "S2", "demonstration": true, "serving_eligible": false, "scenario_class": "observation_ready", "d4_situation_class": "SC-D4-3", "interaction_pattern_family_id": "IPF-D4-03", "administration_form_id": "AF-S2-SEVEN-BEAT", "name_clearance_claim": "CLEARED", "compatibility_class": null, "source_sheet": {"source_sheet_text": "`recipient_roles`: RR-01 the program manager (`intended_recipient`); RR-02 the six colleagues; RR-03 the shared folder as the record. `material_items`: MI-01 that the note makes March conditional on the second data feed; MI-02 the end-of-January condition; MI-03 that the feed has not arrived; MI-04 that the note is unedited in the shared folder. `designated_answer_contents`: AC-01 the note text as the record holds it. `unconfirmed_items`: explicit none — THE RECORD IS COMPLETE, so Q-D4-05 is not served. `available_channels`: CH-01 the meeting (performable true, observable true, eligible); CH-02 recirculating the note (performable false, an intention, not eligible). `designated_points`: B3 to B6. `question_put`: \"What did the note actually say?\" at B4. `contradicted_attribution`: the program manager quotes \"We can hit the March date\"; the record holds the full conditional sentence. Both texts are in the source. `adverse_effect_party`: explicit none. `escalation_state`: explicit none. `conflicting_instructions`: explicit none. `ungrantable_request`: explicit none. `statement_test_point`: B6. `stated_standard`: the note text at the pre-brief. `unsupported_inferences`: that correcting the record publicly was required or unwise. `irrelevant_conduct`: whether the misquote was deliberate; the participant''s manner.", "d4_situation_class": "SC-D4-3"}, "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable roles"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "On A2 or A3"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "On A1"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "Order recoverable across four beats"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "On A1"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "One designated answer content"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "On A1"}, {"question": "Q-D4-05", "state": "NOT SERVED", "basis": "No unconfirmed item. NO ANSWER ROW, NO MISSING-STATE CODE"}, {"question": "Q-D4-05b", "state": "NOT SERVED", "basis": "Its parent is not served"}, {"question": "Q-D4-06", "state": "DIRECT", "basis": "ALL OF A1 TO A4 REACHABLE — the fixture that exercises CE-D4-06 in full"}, {"question": "Q-D4-07", "state": "DIRECT", "basis": "The meeting is a channel used in session. CH-02 NOT eligible"}, {"question": "Q-D4-07b", "state": "CONDITIONAL", "basis": "On A1 or A2"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "B5 asks what is circulated and to whom"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "Test point at B6"}], "script": null, "reveals": [], "text_blocks": {}, "narrative": {"Participant pre-brief": "You are in a planning meeting with six colleagues. What the record shows: last week you wrote in a status note, \"We can hit the March date if the second data feed arrives by the end of January; without it, March is not achievable.\" The note is in the shared folder and has not been edited. The second data feed has not arrived.", "Mentor brief": "The mentor reads the scripted lines of the program manager, once each, at the scripted beats. The mentor does not defend the quotation, does not repeat it, and does not react. NO MENTOR CUE IN THIS FIXTURE REFERS TO TONE, PACE OR MANNER.", "The four questions": "B3 — \"Is that not what you wrote?\" B4 — \"What did the note actually say?\" B5 — \"What are you circulating after this, and to whom?\" B6 — \"Just so I have it right — you''re saying I read it wrong. Is that it?\"", "What this fixture proves": "CE-D4-06 is served only where a source contradicts an attributed statement. It is fully exercised here and not served in the other three fixtures. A build that hard-codes either behavior passes one fixture and fails three."}, "source_version_hash": "076fab1f83a4458990bb3dc828f8f98300735338122fe2650e8940fb97010598"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D4-S2-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
insert into public.t3a_source_authorship(source_version_id, source_author_identity) select v.content_version_id, array['DEMONSTRATION_AUTHOR'] from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D4-S2-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 1, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D4-S2-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 2, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D4-S2-001' on conflict do nothing;
insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D4-S3-001', 'source'::public.t3a_content_family, 'The three groups and the withdrawn date', 'D4', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D4-S3-001", "title": "The three groups and the withdrawn date", "stage": 3, "stage_code": "S3", "demonstration": true, "serving_eligible": false, "scenario_class": "work_sample", "d4_situation_class": "SC-D4-2", "interaction_pattern_family_id": "IPF-D4-02", "administration_form_id": "AF-S3-ASYNC-SUBMISSION", "name_clearance_claim": "CLEARED", "compatibility_class": null, "source_sheet": {"source_sheet_text": "`recipient_roles`: RR-01 the users (`intended_recipient`); RR-02 the receiving service; RR-03 the outgoing supplier. `material_items`: MI-01 that the date is withdrawn; MI-02 that no replacement date is set; MI-03 that a dependency confirmation is outstanding; MI-04 that the users were given the original date in writing eleven days ago. `designated_answer_contents`: AC-01 that the date no longer stands; AC-02 when the next update comes. `unconfirmed_items`: UC-01 the replacement date; UC-02 the dependency timescale. `available_channels`: CH-01 a written communication to the users (evidenced in the submitted work, eligible); CH-02 written notes to the other two groups (evidenced, eligible); CH-03 a joint call (evidenced as proposed, eligible). `designated_points`: before the withdrawn date. `question_put`: the brief asks what the users are told. `contradicted_attribution`: not_applicable — CE-D4-06 NOT IN LAUNCH DESIGN AT STAGE 3. `adverse_effect_party`: the users. `escalation_state`: explicit none. `conflicting_instructions`: explicit none. `ungrantable_request`: a replacement date, which does not exist. `statement_test_point`: not_applicable — CE-D4-09 NOT IN LAUNCH DESIGN AT STAGE 3. `stated_standard`: \"the users'' notice was issued eleven days ago and named the date.\" Exact brief text. `unsupported_inferences`: that any group should hear first; that the withdrawal reflects on anyone. `irrelevant_conduct`: who holds the dependency, WHICH IS A D2 MATTER.", "d4_situation_class": "SC-D4-2"}, "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable groups"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "On A2 or A3"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "On A1"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "The written communication makes the order recoverable"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "On A1"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "The brief puts the question"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "On A1"}, {"question": "Q-D4-05", "state": "DIRECT", "basis": "Two unconfirmed items"}, {"question": "Q-D4-05b", "state": "CONDITIONAL", "basis": "On A1 or A2"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "Stage 3 launch design. NO ANSWER ROW, NO MISSING-STATE CODE"}, {"question": "Q-D4-07", "state": "DIRECT", "basis": "Three channels evidenced"}, {"question": "Q-D4-07b", "state": "CONDITIONAL", "basis": "On A1 or A2"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "The brief asks when the next update comes"}, {"question": "Q-D4-09", "state": "NOT SERVED", "basis": "Stage 3 launch design. NO ANSWER ROW, NO MISSING-STATE CODE"}], "script": null, "reveals": [], "text_blocks": {"The brief as the participant meets it": "A service transition date has been withdrawn. What the record shows: the original date was the first of next month; it is withdrawn because a dependency owner has not confirmed readiness; no replacement date has been set; three groups are affected — the receiving service, the outgoing supplier, and the users who were told the original date in writing; the users'' notice was issued eleven days ago and named the date; and the dependency owner has given no timescale.\nProduce: the communication to the users; a note stating what each of the other two groups is told and when; and a statement of what is not yet known and who must resolve it."}, "narrative": {"The brief as the participant meets it": "> A service transition date has been withdrawn. What the record shows: the original date was the first of next month; it is withdrawn because a dependency owner has not confirmed readiness; no replacement date has been set; three groups are affected — the receiving service, the outgoing supplier, and the users who were told the original date in writing; the users'' notice was issued eleven days ago and named the date; and the dependency owner has given no timescale.\n>\n> Produce: the communication to the users; a note stating what each of the other two groups is told and when; and a statement of what is not yet known and who must resolve it.", "Submission": "Asynchronous. `min_seconds`, `max_seconds` and `mentor_action_sequence` NULL — null is not an error. Eleven provenance fields, three declarations, AI_USE_DECLARATION_REQUIRED in force; a missing tooling declaration refuses and logs.", "What this fixture proves": "Two questions produce no row of any kind while Q-D4-07 is fully reachable — the reverse of the Stage 1 fixture. A build that couples channel availability to Stage, or that writes a null or a not_applicable for an unserved question, has failed."}, "source_version_hash": "1925ada474d35f1fa7888b0aa7def8d6d250009e4ea160c9e0c5744c35d6528f"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D4-S3-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
insert into public.t3a_source_authorship(source_version_id, source_author_identity) select v.content_version_id, array['DEMONSTRATION_AUTHOR'] from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D4-S3-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 1, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D4-S3-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 2, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D4-S3-001' on conflict do nothing;
insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('DEMO-D4-S4-001', 'source'::public.t3a_content_family, 'The update the system cannot produce', 'D4', 'not_loaded'::public.t3a_operational_state) on conflict do nothing;
insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"source_identifier": "DEMO-D4-S4-001", "title": "The update the system cannot produce", "stage": 4, "stage_code": "S4", "demonstration": true, "serving_eligible": false, "scenario_class": "team_simulation", "d4_situation_class": "SC-D4-7", "interaction_pattern_family_id": "IPF-D4-07", "administration_form_id": "AF-S4-GROUP-ROUND", "name_clearance_claim": "CLEARED", "compatibility_class": null, "source_sheet": {"source_sheet_text": "`recipient_roles`: RR-01 the board committee (`intended_recipient`); RR-02 the secretariat; RR-03 the supplier liaison. `material_items`: MI-01 that none of the four measures is available; MI-02 that the last issued figures are three weeks old; MI-03 that no restoration time has been given; MI-04 that the terms require a report at each meeting. `designated_answer_contents`: AC-01 what can be given from the last issued report, identified as three weeks old; AC-02 when current figures follow. `unconfirmed_items`: UC-01 every current measure; UC-02 the restoration time. `available_channels`: CH-01 the committee meeting (performable true, observable true, eligible); CH-02 a written interim note (performable in session as a stated commitment, observable true, eligible); CH-03 the standard report on restoration (performable false, an intention, not eligible). `designated_points`: this afternoon; on restoration. `question_put`: \"What does the committee get?\" at B4. `contradicted_attribution`: explicit none, so Q-D4-06 is not served. `adverse_effect_party`: the board committee. `escalation_state`: explicit none. `conflicting_instructions`: explicit none. `ungrantable_request`: the standard report, which cannot be produced. `statement_test_point`: B6, putting an assertion the record contradicts. `stated_standard`: \"the committee''s terms require a report at each meeting.\" Exact pre-brief text. `unsupported_inferences`: that the meeting should be deferred; that three-week-old figures should or should not be used. `irrelevant_conduct`: the co-participants'' statements, WHICH DESIGNATE NOTHING; the system failure.", "d4_situation_class": "SC-D4-7"}, "question_applicability": [{"question": "Q-D4-01", "state": "DIRECT", "basis": "Three addressable roles"}, {"question": "Q-D4-01b", "state": "CONDITIONAL", "basis": "On A2 or A3"}, {"question": "Q-D4-02", "state": "DIRECT", "basis": "Four designated items"}, {"question": "Q-D4-02b", "state": "CONDITIONAL", "basis": "On A1"}, {"question": "Q-D4-03", "state": "DIRECT", "basis": "Order recoverable"}, {"question": "Q-D4-03b", "state": "CONDITIONAL", "basis": "On A1"}, {"question": "Q-D4-04", "state": "DIRECT", "basis": "A direct question at B4"}, {"question": "Q-D4-04b", "state": "CONDITIONAL", "basis": "On A1"}, {"question": "Q-D4-05", "state": "DIRECT", "basis": "Two unconfirmed items"}, {"question": "Q-D4-05b", "state": "CONDITIONAL", "basis": "On A1 or A2"}, {"question": "Q-D4-06", "state": "NOT SERVED", "basis": "No contradicted attribution. NO ANSWER ROW, NO MISSING-STATE CODE"}, {"question": "Q-D4-07", "state": "DIRECT", "basis": "Two channels performable in session; CH-03 NOT eligible"}, {"question": "Q-D4-07b", "state": "CONDITIONAL", "basis": "On A1 or A2"}, {"question": "Q-D4-08", "state": "DIRECT", "basis": "B5 asks what follows and by when"}, {"question": "Q-D4-09", "state": "DIRECT", "basis": "Test point at B6, and A3 is reachable"}], "script": null, "reveals": [], "text_blocks": {}, "narrative": {"Model": "ONE OBSERVED PARTICIPANT (P-OBS), THREE CO-PARTICIPANTS (CP-1, CP-2, CP-3) who are role players and are NOT observed, one facilitator. ONE OBSERVATION RECORD, for P-OBS only. A Stage 4 group participation record is required for all four before entry. No recording.", "P-OBS pre-brief": "A governance report is due to a board committee this afternoon and the reporting system is unavailable. What the record shows: the report draws four measures from that system; none is available; the last issued report holds figures from three weeks ago; the committee''s terms require a report at each meeting; and the supplier has given no restoration time.", "CP positions": "CP-1, the secretariat: state that the terms require a report. CP-2, a workstream lead: state that your position has not changed since the last report. CP-3, the supplier liaison: state that no restoration time has been given.", "Facilitator card": "As Section 5.18, including: YOU MAKE NO NOTE OF HOW ANYTHING WAS SAID.", "The four questions": "B3 — \"What is the report this afternoon?\" B4 — \"None of the four measures is available. What does the committee get?\" B5 — \"What follows, to whom, and by when?\" B6 — \"Just so the position is right — you said the last report''s figures are current. Are they?\"", "What this fixture proves": "CP-1 states that the terms require a report and CP-3 states that no restoration time is given — both restate facts the pre-brief already establishes. THE SOURCE SHEET ESTABLISHES THEM; THE CO-PARTICIPANTS DO NOT. A build that lets a co-participant position populate `material_items` or `unconfirmed_items` will pass the other three fixtures and fail here."}, "source_version_hash": "a1762ea257932c9b5736bc86da85d41a3c4c1f9d4c55e3a12102c1ab67b10a77"}'::jsonb from public.t3a_content_object where identifier = 'DEMO-D4-S4-001' and not exists (select 1 from public.t3a_d1_content_version v where v.content_object_id = t3a_content_object.content_object_id);
insert into public.t3a_source_authorship(source_version_id, source_author_identity) select v.content_version_id, array['DEMONSTRATION_AUTHOR'] from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D4-S4-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 1, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D4-S4-001' on conflict do nothing;
insert into public.t3a_source_drafting_test(source_version_id, test_no, outcome, reviewer_identity, tested_on, version_tested_ref) select v.content_version_id, 2, 'demonstration_only', 'DEMONSTRATION_REVIEWER', current_date, v.version_no from public.t3a_d1_content_version v join public.t3a_content_object o using (content_object_id) where o.identifier = 'DEMO-D4-S4-001' on conflict do nothing;
